@section('scripts')
<script>
    $(document).ready(function() {
        var images = [
            "{{asset('images/event-managment/image1.jpg')}}"
            , "{{asset('images/event-managment/image2.jpg')}}"
            , "{{asset('images/event-managment/image3.jpg')}}"
            , "{{asset('images/event-managment/image4.jpg')}}"
        ]; // Array of image URLs
        var currentImage = 0;

        setInterval(function() {
            // Change the image source
            $("#slideImage").attr("src", images[currentImage]);

            // Increment currentImage counter
            currentImage++;

            // Reset counter if it exceeds the number of images
            if (currentImage >= images.length) {
                currentImage = 0;
            }
        }, 2000); // Change image every 2 seconds (2000 milliseconds)
    });

</script>
